#!/usr/bin/env python3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.request import Request, urlopen
import json, os, sys

MODEL_NAME=os.environ.get('MODEL_NAME','fraud-detection-deploy')
MODEL_HOST=os.environ.get('MODEL_HOST','http://fraud-detection-deploy-predictor.fraud-detection.svc.cluster.local:8080')
MODEL_URL=os.environ.get('MODEL_URL',f'{MODEL_HOST}/v2/models/{MODEL_NAME}/infer')
MODEL_META_URL=os.environ.get('MODEL_META_URL',f'{MODEL_HOST}/v2/models/{MODEL_NAME}')
APP_HOST=os.environ.get('APP_HOST','0.0.0.0')
APP_PORT=int(os.environ.get('APP_PORT','8080'))

HTML=r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meridian Financial | Transaction Risk Review</title>
<style>
:root{--bg:#07111e;--panel:#0d1a2b;--panel2:#13243a;--line:#24384f;--text:#f7fbff;--muted:#9db0c4;--accent:#53a8ff;--good:#3fd08c;--warn:#f0b64c;--bad:#f46464}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,-apple-system,sans-serif;background:linear-gradient(180deg,#08131f,#0a1624);color:var(--text);min-height:100vh}.shell{max-width:1240px;margin:auto;padding:24px}.topbar{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:10px 0 22px;border-bottom:1px solid rgba(255,255,255,.06);margin-bottom:24px}.brand{display:flex;align-items:center;gap:14px}.bankmark{width:44px;height:44px;border-radius:11px;background:linear-gradient(135deg,#0e4f88,#2f86d7);display:grid;place-items:center;font-weight:800}.brand h1{margin:0;font-size:20px}.sub{color:var(--muted);font-size:12px;margin-top:3px}.top-actions{display:flex;gap:10px;flex-wrap:wrap}.badge{display:flex;gap:8px;align-items:center;border:1px solid var(--line);background:rgba(13,26,43,.8);padding:8px 11px;border-radius:999px;font-size:12px;color:var(--muted)}.dot{width:8px;height:8px;border-radius:50%;background:#6f7c89}.dot.ok{background:var(--good);box-shadow:0 0 12px rgba(63,208,140,.55)}.dot.bad{background:var(--bad)}.context{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:14px;margin-bottom:18px}.tile{border:1px solid var(--line);background:rgba(13,26,43,.76);border-radius:14px;padding:14px 16px}.eyebrow{text-transform:uppercase;letter-spacing:1.25px;font-size:10px;color:#7f93a9;margin-bottom:5px}.value{font-size:14px;font-weight:700}.small{font-size:12px;color:var(--muted);margin-top:3px;line-height:1.4}.grid{display:grid;grid-template-columns:1.05fr .95fr;gap:20px}.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;box-shadow:0 18px 55px rgba(0,0,0,.18)}.card h2{font-size:16px;margin:0 0 4px}.intro{color:var(--muted);font-size:12px;margin-bottom:18px}.presets{display:flex;gap:8px;margin-bottom:18px;flex-wrap:wrap}button{border:0;border-radius:9px;font-weight:700;cursor:pointer}.ghost{background:var(--panel2);border:1px solid var(--line);color:var(--text);padding:8px 11px;font-size:12px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:13px}label{display:block;color:var(--muted);font-size:11px;margin-bottom:6px}input[type=number],input[type=text]{width:100%;border:1px solid var(--line);background:#091523;color:var(--text);padding:10px 11px;border-radius:9px;font-size:13px}.toggles{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;grid-column:1/-1}.toggle{display:flex;justify-content:space-between;align-items:center;border:1px solid var(--line);background:#091523;border-radius:9px;padding:10px 11px}.toggle span{font-size:11px;color:var(--muted)}input[type=checkbox]{width:17px;height:17px}.analyze{width:100%;margin-top:18px;padding:12px;color:#fff;background:linear-gradient(135deg,#2377c9,#2d6cdf);font-size:14px}.result{min-height:440px;display:flex;flex-direction:column;justify-content:center}.empty{text-align:center;color:var(--muted);padding:65px 10px}.empty strong{display:block;color:var(--text);font-size:20px;margin-bottom:5px}.score{font-size:62px;font-weight:800;line-height:1;margin:9px 0 8px;letter-spacing:-2px}.risk{display:inline-flex;width:max-content;border:1px solid currentColor;border-radius:999px;padding:6px 9px;font-size:11px;font-weight:800;letter-spacing:.8px}.low{color:var(--good)}.medium{color:var(--warn)}.high{color:var(--bad)}.reco{font-size:18px;font-weight:800;margin-top:13px}.detail{font-size:12px;line-height:1.5;color:var(--muted);margin-top:7px}.bar{height:8px;background:#07111e;border:1px solid var(--line);border-radius:20px;overflow:hidden;margin:17px 0 5px}.bar>div{height:100%;width:0;background:linear-gradient(90deg,var(--good),var(--warn),var(--bad));transition:.4s width}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:16px}.metric{background:#091523;border:1px solid var(--line);border-radius:10px;padding:11px}.mval{font-weight:800;font-size:13px}.mlabel{font-size:10px;color:var(--muted);margin-top:3px}.flow{margin-top:18px;padding:13px;border:1px solid var(--line);border-radius:11px;background:#091523}.flowline{font-size:11px;color:#c8d5e3;line-height:1.7}.flowline span{color:var(--accent);font-weight:700}details{margin-top:14px;border-top:1px solid var(--line);padding-top:12px}summary{cursor:pointer;font-size:12px;color:#c8d5e3}pre{white-space:pre-wrap;word-break:break-word;background:#06101c;border:1px solid var(--line);border-radius:9px;padding:11px;font-size:10px;max-height:210px;overflow:auto;color:#c7d4e1}.error{color:var(--bad);border:1px solid rgba(244,100,100,.4);padding:10px;border-radius:9px;margin-top:10px;font-size:12px}.footer{margin-top:14px;color:#71859b;font-size:10px;text-align:center}@media(max-width:900px){.grid{grid-template-columns:1fr}.fields{grid-template-columns:1fr}.toggles{grid-template-columns:1fr}}
</style></head><body><div class="shell">
<div class="topbar"><div class="brand"><div class="bankmark">MF</div><div><h1>Meridian Financial</h1><div class="sub">Fraud Engineering • Transaction Risk Review</div></div></div><div class="top-actions"><div class="badge"><span id="statusDot" class="dot"></span><span id="statusText">Checking model…</span></div><div class="badge">Environment: OpenShift AI</div></div></div>
<div class="grid"><section class="card"><h2>Transaction validation</h2><div class="intro">Simulate what a Meridian engineer would use to validate model behavior before handing the endpoint to a fraud operations application.</div><div class="presets"><button class="ghost" onclick="preset('normal')">Load expected transaction</button><button class="ghost" onclick="preset('suspicious')">Load suspicious transaction</button></div><div class="fields"><div><label>Transaction ID</label><input id="txnId" type="text" value="TXN-842913"></div><div><label>Customer ID</label><input id="customerId" type="text" value="CUST-18492"></div><div><label>Transaction amount ($)</label><input id="amount" type="number" value="84.25" step="0.01"></div><div><label>Merchant</label><input id="merchant" type="text" value="Meridian Market"></div><div><label>Distance from previous transaction (miles)</label><input id="distance" type="number" value="0.31114" step="0.01"></div><div><label>Purchase vs. customer median</label><input id="ratio" type="number" value="1.94594" step="0.01"></div><div class="toggles"><div class="toggle"><span>Chip used</span><input id="chip" type="checkbox" checked></div><div class="toggle"><span>PIN used</span><input id="pin" type="checkbox"></div><div class="toggle"><span>Online order</span><input id="online" type="checkbox"></div></div></div><button id="analyzeBtn" class="analyze" onclick="analyze()">Validate against deployed model</button><div id="errorBox"></div></section>
<section class="card result"><div id="emptyState" class="empty"><strong>Ready for engineer validation</strong>Load a transaction and call the same standardized model endpoint a downstream application would consume.</div><div id="resultState" style="display:none"><div class="eyebrow">Model output • fraud probability</div><div id="score" class="score">0.0%</div><div id="riskPill" class="risk low">LOW RISK</div><div id="recommendation" class="reco">Approve transaction</div><div id="detail" class="detail"></div><div class="bar"><div id="riskBar"></div></div><div class="metrics"><div class="metric"><div id="decisionClass" class="mval">—</div><div class="mlabel">Model classification</div></div><div class="metric"><div class="mval">fraud-detection-deploy</div><div class="mlabel">Serving model</div></div><div class="metric"><div class="mval">ONNX / MLServer</div><div class="mlabel">Runtime</div></div><div class="metric"><div class="mval">KServe V2</div><div class="mlabel">Inference contract</div></div></div><div class="flow"><div class="eyebrow">What Meridian standardized</div><div class="flowline">Data scientist → <span>OpenShift AI Workbench</span> → ONNX artifact → <span>KServe / MLServer</span> → standardized endpoint → fraud application</div></div><details><summary>Engineer view: inspect live inference request / response</summary><div class="eyebrow" style="margin-top:12px">KServe request</div><pre id="requestJson"></pre><div class="eyebrow">KServe response</div><pre id="responseJson"></pre></details></div></section></div><div class="footer">Meridian Financial demo environment • OpenShift AI model serving validation workflow</div></div>
<script>
const PRESETS={normal:{txnId:'TXN-842913',customerId:'CUST-18492',amount:84.25,merchant:'Meridian Market',distance:.3111400080477545,ratio:1.9459399775518593,chip:true,pin:false,online:false},suspicious:{txnId:'TXN-991204',customerId:'CUST-18492',amount:4875.50,merchant:'ElectroWorld Online',distance:950,ratio:12,chip:false,pin:false,online:true}};
function preset(n){const p=PRESETS[n];txnId.value=p.txnId;customerId.value=p.customerId;amount.value=p.amount;merchant.value=p.merchant;distance.value=p.distance;ratio.value=p.ratio;chip.checked=p.chip;pin.checked=p.pin;online.checked=p.online}
async function checkModel(){try{const r=await fetch('/api/model');if(!r.ok)throw 0;statusDot.className='dot ok';statusText.textContent='Model online'}catch(e){statusDot.className='dot bad';statusText.textContent='Model unavailable'}}
async function analyze(){errorBox.innerHTML='';analyzeBtn.disabled=true;analyzeBtn.textContent='Validating…';const body={distance_from_last_transaction:Number(distance.value),ratio_to_median_purchase_price:Number(ratio.value),used_chip:chip.checked?1:0,used_pin_number:pin.checked?1:0,online_order:online.checked?1:0};try{const r=await fetch('/api/predict',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Prediction failed');const pct=j.fraud_probability*100;let level,cls,rec;if(pct>=70){level='HIGH RISK';cls='high';rec='Hold transaction for fraud review'}else if(pct>=30){level='MEDIUM RISK';cls='medium';rec='Require step-up verification'}else{level='LOW RISK';cls='low';rec='Approve transaction'}emptyState.style.display='none';resultState.style.display='block';score.textContent=pct.toFixed(1)+'%';riskPill.className='risk '+cls;riskPill.textContent=level;recommendation.textContent=rec;decisionClass.textContent=j.label===1?'Fraud':'Legitimate';detail.textContent='The score was returned by Meridian’s deployed OpenShift AI inference service, not calculated in this UI.';riskBar.style.width=Math.max(.5,pct)+'%';requestJson.textContent=JSON.stringify(j.model_request,null,2);responseJson.textContent=JSON.stringify(j.raw_model_response,null,2)}catch(e){errorBox.innerHTML='<div class="error">'+e.message+'</div>'}finally{analyzeBtn.disabled=false;analyzeBtn.textContent='Validate against deployed model'}}
checkModel();
</script></body></html>'''

def call_json(url,payload=None):
    req=Request(url,method='GET') if payload is None else Request(url,data=json.dumps(payload).encode(),method='POST',headers={'Content-Type':'application/json'})
    with urlopen(req,timeout=8) as r:return json.loads(r.read().decode())

def model_request(d):
    return {'inputs':[{'name':'float_input','shape':[1,5],'datatype':'FP32','data':[float(d['distance_from_last_transaction']),float(d['ratio_to_median_purchase_price']),float(d['used_chip']),float(d['used_pin_number']),float(d['online_order'])]}],'outputs':[{'name':'label'},{'name':'probabilities'}]}

class Handler(BaseHTTPRequestHandler):
    def log_message(self,fmt,*args):sys.stdout.write('[meridian-ui] '+fmt%args+'\n')
    def send_json(self,code,obj):
        b=json.dumps(obj).encode();self.send_response(code);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
    def do_GET(self):
        if self.path=='/healthz':
            self.send_json(200,{'status':'ok'})
        elif self.path=='/':
            b=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
        elif self.path=='/api/model':
            try:self.send_json(200,call_json(MODEL_META_URL))
            except Exception as e:self.send_json(503,{'error':str(e)})
        else:self.send_error(404)
    def do_POST(self):
        if self.path!='/api/predict':return self.send_error(404)
        try:
            n=int(self.headers.get('Content-Length','0'));d=json.loads(self.rfile.read(n).decode());req=model_request(d);raw=call_json(MODEL_URL,req);outs={x.get('name'):x for x in raw.get('outputs',[])};label=int(outs['label']['data'][0]);probs=outs['probabilities']['data'];self.send_json(200,{'label':label,'fraud_probability':float(probs[1]),'not_fraud_probability':float(probs[0]),'model_request':req,'raw_model_response':raw})
        except Exception as e:self.send_json(500,{'error':str(e)})

if __name__=='__main__':
    print(f'Meridian demo UI listening on http://{APP_HOST}:{APP_PORT}')
    print(f'Model metadata URL: {MODEL_META_URL}')
    ThreadingHTTPServer((APP_HOST,APP_PORT),Handler).serve_forever()
